pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        address nft = address(0xdead);
        c.initialize(
            address(0),
            nft,
            100 ether,
            100 ether,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        bool success;
        try c.availableForFlashLoan(nft, 1) returns (bool) {
            success = true;
        } catch {
            success = false;
        }

        assertEq(c.nft(), nft);
    }
}
